SELECT FirstName + ' ' + MiddleName + ' ' + LastName
FROM Person.Person;
-- A NULL MiddleName makes the WHOLE result NULL

-- Oracle and PostgreSQL share this syntax exactly
SELECT first_name || ' ' || last_name AS full_name
FROM employees;

-- WRONG on MySQL: + is arithmetic, not string concatenation
SELECT first_name + ' ' + last_name FROM employees;

-- RIGHT: CONCAT() is required
SELECT CONCAT(first_name, ' ', last_name) FROM employees;

-- Works on SQL Server, Oracle, MySQL, and PostgreSQL
SELECT CONCAT(FirstName, ' ', MiddleName, ' ', LastName)
FROM Person.Person;
